/* User-activated Japanese speech synthesis; serial jobs, never overlapping. */
(() => {
 'use strict';
 const A=window.RAIL_ANNOUNCEMENT_MODEL,synth=window.speechSynthesis,supported=!!(synth&&window.SpeechSynthesisUtterance),$=id=>document.getElementById(id);
 let getState,save,notify,ready=false,queue=[],active=null,generation=0,startTimer,endTimer,timer=null,voices=[],lastText='',status=supported?'点击启用声音，或点击列车名播报':'此浏览器不支持语音合成';
 const storageKey='n-gauge-arrival-seen-v1';let seen=new Set(),seenDate='';
 function sync(){if(!$('announcement-status'))return;$('announcement-status').textContent=status+` · 等待 ${queue.length} 班`;$('announcement-transcript').textContent=lastText;$('enable-audio').textContent=ready?'声音已启用 · 试听':'启用声音 · 试听';$('sound-toggle').dataset.ready=String(ready);$('sound-toggle').setAttribute('aria-pressed',String(ready));$('sound-toggle').title=ready?'声音已启用；点击停止并关闭':'启用日语到站播报';for(const row of document.querySelectorAll('.departure'))row.classList.toggle('announcing',row.dataset.rowId===active?.rowId);}
 function setStatus(s){status=s;sync();}
 function loadSeen(date){if(seenDate!==date){seenDate=date;seen=new Set();}try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved?.date===date)for(const k of saved.keys||[])if(typeof k==='string'&&k.startsWith(date+'|'))seen.add(k);}catch(_){}}
 function markSeen(keys,date){loadSeen(date);keys.forEach(k=>seen.add(k));try{localStorage.setItem(storageKey,JSON.stringify({date,keys:[...seen].slice(-300)}));}catch(_){}}
 function stop(disable=false){generation++;queue=[];active=null;clearTimeout(startTimer);clearTimeout(endTimer);if(supported)synth.cancel();if(disable)ready=false;setStatus(disable?'声音已关闭；自动播报等待再次启用':'已停止播报并清空队列');}
 function refreshVoices(){if(!supported)return;voices=synth.getVoices().filter(v=>/^ja(?:-|_)/i.test(v.lang));const node=$('announcement-voice');if(!node)return;const wanted=getState?.().announcements.voiceURI||node.value;node.replaceChildren();const def=document.createElement('option');def.value='';def.textContent=voices.length?'自动选择日语声音':'系统日语（等待设备返回声音列表）';node.append(def);voices.forEach(v=>{const o=document.createElement('option');o.value=v.voiceURI;o.textContent=v.name+' · '+v.lang;node.append(o);});node.value=voices.some(v=>v.voiceURI===wanted)?wanted:'';}
 function next(){if(active||!queue.length||!ready)return;const job=queue.shift(),token=generation,settings=getState().announcements,u=new SpeechSynthesisUtterance(job.text);active=job;job.utterance=u;lastText=job.text;u.lang='ja-JP';u.rate=settings.rate;u.volume=settings.volume;const voice=voices.find(v=>v.voiceURI===settings.voiceURI)||voices.find(v=>v.localService)||voices[0];if(voice)u.voice=voice;
  const finish=error=>{if(token!==generation||active!==job)return;clearTimeout(startTimer);clearTimeout(endTimer);active=null;if(error){setStatus('本班语音失败：'+error);if(['not-allowed','language-unavailable','voice-unavailable','start-timeout'].includes(error)){ready=false;queue=[];sync();notify?.('声音未能启动，请点击“启用声音”重试，并检查设备日语声音');return;}}else setStatus('本班播报完成');next();};
  u.onstart=()=>{if(token!==generation)return;clearTimeout(startTimer);setStatus('正在播报：'+job.label);};u.onend=()=>finish();u.onerror=e=>finish(e.error||'unknown');
  setStatus('准备播报：'+job.label);startTimer=setTimeout(()=>{if(active===job){generation++;active=null;queue=[];ready=false;synth.cancel();setStatus('未能启动声音，请点击重新启用');}},12000);endTimer=setTimeout(()=>{if(active===job){generation++;active=null;synth.cancel();setStatus('本班语音超时，已停止');next();}},90000);
  try{synth.speak(u);}catch(e){finish(e.name||'synthesis-failed');}
 }
 function enqueue(jobs){if(!supported||!ready)return false;if(queue.length+jobs.length+(active?1:0)>10){notify?.('播报队列已满，请等待或停止后重试');return false;}queue.push(...jobs);next();sync();return true;}
 function enable(test=true){if(!supported){notify?.('此浏览器不支持语音合成');return false;}ready=true;refreshVoices();setStatus('声音已启用'+(getState().announcements.auto?' · 日本时间自动播报已开启':''));if(test)enqueue([{rowId:'test',label:'日语声音试听',text:'まもなく、電車がまいります。これは模型駅の音声テストです。'}]);return true;}
 function request(row){if(!ready&&!enable(false))return;enqueue([A.message(getState(),row)]);}
 function tick(now=new Date()){if(!ready||!getState?.().announcements.auto||document.hidden)return;const stamp=A.jst(now);loadSeen(stamp.date);const jobs=A.due(getState(),now,seen);if(jobs.length&&enqueue(jobs))markSeen(jobs.map(j=>j.key),stamp.date);}
 function rowControl(row){const wrap=document.createElement('div');wrap.className='row-announcement';const button=document.createElement('button');button.type='button';button.className='small-button';button.textContent='播报这班到站';button.addEventListener('click',()=>request(row));const note=document.createElement('p');note.className='theme-note';const details=document.createElement('details'),summary=document.createElement('summary'),text=document.createElement('p');summary.textContent='查看到站播报文案';text.className='announcement-preview';wrap.update=()=>{const m=A.message(getState(),row);note.textContent=m.referenceNote;text.textContent=m.text;};wrap.update();details.append(summary,text);wrap.append(button,note,details);return wrap;}
 function bind(stateGetter,onChange,onNotice){getState=stateGetter;save=onChange;notify=onNotice;refreshVoices();synth?.addEventListener?.('voiceschanged',refreshVoices);$('enable-audio').disabled=$('announcement-auto').disabled=!supported;
  $('enable-audio').addEventListener('click',()=>{enable(true);tick();});$('sound-toggle').addEventListener('click',()=>ready?stop(true):enable(true));$('stop-announcements').addEventListener('click',()=>stop());
  $('announcement-auto').addEventListener('change',e=>{getState().announcements.auto=e.target.checked;if(e.target.checked&&!ready)enable(false);if(!e.target.checked)stop();save();setStatus(e.target.checked?'自动播报已开启：按日本时间匹配当前四行，外圈优先':'自动播报已关闭');tick();});
  for(const [id,key] of [['announcement-volume','volume'],['announcement-rate','rate'],['announcement-voice','voiceURI']])$(id).addEventListener('change',()=>{getState().announcements[key]=key==='voiceURI'?$(id).value:Number($(id).value);save();});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();setStatus('页面在后台；到站自动播报已暂停，不补播错过分钟');}else{sync();tick();}});window.addEventListener('pagehide',()=>stop(true));timer=setInterval(tick,1000);sync();
 }
 function syncSettings(){if(!getState)return;const s=getState().announcements;$('announcement-auto').checked=s.auto;$('announcement-volume').value=s.volume;$('announcement-rate').value=s.rate;$('announcement-voice').value=voices.some(v=>v.voiceURI===s.voiceURI)?s.voiceURI:'';for(const row of document.querySelectorAll('.row-announcement'))row.update?.();sync();}
 window.RAIL_ANNOUNCEMENTS={bind,request,rowControl,sync:syncSettings,stop,tick};
})();
